"""policy.ini (docs/policy.md)."""

import re
from datetime import timedelta
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

DEFAULTS = {
    "max_size": None, "max_age": None, "naming": "numbered", "offset": "+00:00",
    "compress_after": 1, "keep": 5, "keep_days": None,
}

_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DURATION = re.compile(r"([0-9]+)([mhd])\Z")
_INT = re.compile(r"[0-9]+\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")


def _bad(msg):
    return DataError("policy", f"policy.ini: {msg}")


def _off(conv):
    return lambda v: None if v == "off" else conv(v)


def _size(v):
    m = _SIZE.match(v)
    if not m:
        raise ValueError(v)
    return int(m[1]) * {"": 1, "k": 1 << 10, "m": 1 << 20, "g": 1 << 30}[m[2].lower()]


def _duration(v):
    m = _DURATION.match(v)
    if not m:
        raise ValueError(v)
    unit = {"m": "minutes", "h": "hours", "d": "days"}[m[2]]
    return timedelta(**{unit: int(m[1])})


def _naming(v):
    if v not in ("numbered", "dated"):
        raise ValueError(v)
    return v


def _offset(v):
    m = _OFFSET.match(v)
    if not m or int(m[2]) > 23 or int(m[3]) > 59:
        raise ValueError(v)
    minutes = int(m[2]) * 60 + int(m[3])
    return timedelta(minutes=-minutes if m[1] == "-" else minutes)


def _int(minimum):
    def conv(v):
        if not _INT.match(v) or int(v) < minimum:
            raise ValueError(v)
        return int(v)
    return conv


CONVERTERS = {
    "max_size": _off(_size), "max_age": _off(_duration), "naming": _naming, "offset": _offset,
    "compress_after": _int(0), "keep": _int(1), "keep_days": _off(_int(1)),
}


def load(path: Path):
    """Returns (defaults section, {stream: section}) with converted values; raises DataError `policy`."""
    if not path.exists():
        return {}, {}
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    defaults, sections = None, {}
    current = None
    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line[0] == "[":
            if not line.endswith("]"):
                raise _bad(f"bad section line: {line}")
            title = line[1:-1]
            if title == "defaults":
                if defaults is not None:
                    raise _bad("section [defaults] twice")
                defaults = current = {}
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    raise _bad(f"section {name} twice")
                sections[name] = current = {}
            else:
                raise _bad(f"unknown section: {title}")
            continue
        if current is None or "=" not in line:
            raise _bad(f"bad line: {line}")
        key, value = (s.strip() for s in line.split("=", 1))
        if key not in CONVERTERS:
            raise _bad(f"unknown key: {key}")
        if key in current:
            raise _bad(f"key {key} twice")
        try:
            current[key] = CONVERTERS[key](value)
        except ValueError:
            raise _bad(f"bad value for {key}: {value}") from None
    return defaults or {}, sections


def settings(policy, name: str) -> dict:
    """The settings of one stream: its section, else [defaults], else the built-in values."""
    defaults, sections = policy
    out = dict(DEFAULTS)
    out.update(defaults)
    out.update(sections.get(name, {}))
    return out
