"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, timedelta, timezone

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_NUM = re.compile(r"([1-9][0-9]*)(\.gz)?\Z")
_DATED = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")


class Archive:
    def __init__(self, name, key, gz, content=None):
        self.name, self.key, self.gz, self.content = name, key, gz, content
        self.new = False
        self.time = None  # the string kept in state.json
        self.final = name


def find_archives(data, name, naming):
    """The archives of a stream, newest first."""
    d = streams.logs_dir(data)
    prefix = f"{name}.log."
    found = {}
    if d.is_dir():
        for p in d.iterdir():
            if not p.is_file() or not p.name.startswith(prefix):
                continue
            rest = p.name[len(prefix):]
            if naming == "numbered":
                m = _NUM.match(rest)
                key = (-int(m[1]),) if m else None
                gz = bool(m and m[2])
            else:
                m = _DATED.match(rest)
                key = None
                if m:
                    try:
                        key = (date.fromisoformat(m[1]), int(m[2] or 1))
                    except ValueError:
                        key = None
                gz = bool(m and m[3])
            if key is None:
                continue
            if key in found:
                raise DataError("archives", f"{p.name}: two archives in the same place")
            found[key] = Archive(p.name, key, gz)
    return [found[k] for k in sorted(found, reverse=True)]


def _first_time(path):
    try:
        with path.open("rb") as f:
            line = f.readline()
    except OSError:
        return None
    text = line.decode("utf-8", errors="replace").rstrip("\r\n")
    return dates.parse_iso(text.split(" ", 1)[0])


def _check_state(entries, existing):
    for name in existing:
        e = entries.get(name)
        if e is None:
            continue
        if "opened" in e and dates.parse_state(e["opened"]) is None:
            raise DataError("state", f"{name}: bad opened")
        if "archives" in e:
            a = e["archives"]
            if not isinstance(a, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for k, v in a.items():
                if dates.parse_state(v) is None:
                    raise DataError("state", f"{name}: bad time for {k}")
        if "rotations" in e:
            r = e["rotations"]
            if not isinstance(r, int) or isinstance(r, bool) or r < 0:
                raise DataError("state", f"{name}: bad rotations")


def run(ctx, requested, dry_run, force):
    pol = policy.load(ctx.policy_path)
    doc = ctx.state
    entries = doc["streams"]
    existing = set(pol[1]) | set(streams.active(ctx.data))
    _check_state(entries, existing)
    if requested:
        for n in requested:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
        names = sorted(set(requested))
    else:
        names = sorted(existing)

    now = ctx.now
    plans = []
    for name in names:
        cfg = policy.settings(pol, name)
        plans.append((name, cfg, find_archives(ctx.data, name, cfg["naming"])))

    out = []
    n_rot = n_rem = n_comp = 0
    new_entries = {}
    actions = []  # (removals, writes) per stream, executed after all checks
    for name, cfg, archives in plans:
        entry = entries.get(name, {})
        log = streams.log_path(ctx.data, name)
        times = entry.get("archives", {})
        for a in archives:
            a.time = times.get(a.name)
        if not log.is_file():
            what = None
            out.append(f"{name}: no log")
        else:
            size = log.stat().st_size
            if size == 0:
                what = None
                out.append(f"{name}: empty")
            elif force:
                what = "forced"
            elif cfg["max_size"] is not None and size >= cfg["max_size"]:
                what = "size"
            else:
                what = None
                if cfg["max_age"] is not None:
                    opened = dates.parse_state(entry["opened"]) if "opened" in entry else _first_time(log)
                    if opened is not None and now - opened >= cfg["max_age"]:
                        what = "age"
                if what is None:
                    out.append(f"{name}: not due")
        if what:
            out.append(f"{name}: rotate ({what})")
            n_rot += 1
            new = Archive(None, None, False, content=log.read_bytes())
            new.new = True
            new.time = dates.stamp(now)
            if cfg["naming"] == "numbered":
                archives.insert(0, new)
            else:
                day = now.astimezone(timezone(cfg["offset"])).date()
                ks = [a.key[1] for a in archives if a.key[0] == day]
                k = max(ks) + 1 if ks else 1
                new.key = (day, k)
                archives.append(new)
                archives.sort(key=lambda a: a.key, reverse=True)
                new.name = f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")
            if cfg["naming"] == "numbered":
                new.key = (0,)
        for a in archives:
            a.old = a.name
        removed = []
        kept = []
        for pos, a in enumerate(archives, 1):
            drop = pos > cfg["keep"]
            if not drop and cfg["keep_days"] is not None and a.time is not None:
                t = dates.parse_state(a.time)
                drop = now - t >= timedelta(days=cfg["keep_days"])
            (removed if drop else kept).append(a)
        for pos, a in enumerate(kept, 1):
            if cfg["naming"] == "numbered":
                a.final = f"{name}.log.{pos}" + (".gz" if a.gz else "")
            elif a.new:
                a.final = a.name
            if pos > cfg["compress_after"] and not a.gz:
                a.gz = True
                a.final += ".gz"
                a.compressed = True
                n_comp += 1
            else:
                a.compressed = False
        for a in kept:
            if a.new:
                out.append(f"  new {a.final}")
            elif a.final != a.old:
                out.append(f"  {a.final} <- {a.old}")
            else:
                out.append(f"  {a.final}")
        for a in removed:
            if not a.new:
                out.append(f"remove {a.old}")
                n_rem += 1
        actions.append((name, log, what, kept, removed))

        e = {}
        if what:
            e["opened"] = dates.stamp(now)
        elif "opened" in entry:
            e["opened"] = entry["opened"]
        e["rotations"] = entry.get("rotations", 0) + (1 if what else 0)
        e["archives"] = {a.final: a.time for a in kept if a.time is not None}
        new_entries[name] = e

    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    d = streams.logs_dir(ctx.data)
    for name, log, what, kept, removed in actions:
        contents = {}
        for a in kept:
            if a.new or a.final != a.old:
                contents[id(a)] = a.content if a.new else (d / a.old).read_bytes()
        for a in removed:
            if not a.new:
                (d / a.old).unlink()
        for a in kept:
            if not a.new and a.final != a.old:
                (d / a.old).unlink()
        for a in kept:
            if id(a) in contents:
                data = contents[id(a)]
                if a.compressed:
                    data = gzip.compress(data, mtime=0)
                (d / a.final).write_bytes(data)
        if what:
            log.write_bytes(b"")
    entries.update(new_entries)
    state.save(ctx.state_path, doc)
    return out
