            if cfg["naming"] == "numbered":
                new.key = (0,)
        for a in archives:
            a.old = a.name
        removed = []
        kept = []
        for pos, a in enumerate(archives, 1):
            drop = pos > cfg["keep"]
            if not drop and cfg["keep_days"] is not None and a.time is not None:
                t = dates.parse_state(a.time)
                drop = now - t >= timedelta(days=cfg["keep_days"])
            (removed if drop else kept).append(a)
        for pos, a in enumerate(kept, 1):
            if cfg["naming"] == "numbered":
                a.final = f"{name}.log.{pos}" + (".gz" if a.gz else "")
            elif a.new:
                a.final = a.name
            if pos > cfg["compress_after"] and not a.gz:
                a.gz = True
                a.final += ".gz"
                a.compressed = True
                n_comp += 1
            else:
                a.compressed = False
        for a in kept:
            if a.new:
                out.append(f"  new {a.final}")
            elif a.final != a.old:
                out.append(f"  {a.final} <- {a.old}")
            else:
                out.append(f"  {a.final}")
        for a in removed:
            if not a.new:
                out.append(f"remove {a.old}")
                n_rem += 1
        actions.append((name, log, what, kept, removed))

        e = {}
        if what:
            e["opened"] = dates.stamp(now)
        elif "opened" in entry:
            e["opened"] = entry["opened"]
        e["rotations"] = entry.get("rotations", 0) + (1 if what else 0)
        e["archives"] = {a.final: a.time for a in kept if a.time is not None}
        new_entries[name] = e

    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    d = streams.logs_dir(ctx.data)
    for name, log, what, kept, removed in actions:
        contents = {}
        for a in kept:
            if a.new or a.final != a.old:
                contents[id(a)] = a.content if a.new else (d / a.old).read_bytes()
        for a in removed:
            if not a.new:
                (d / a.old).unlink()
        for a in kept:
            if not a.new and a.final != a.old:
                (d / a.old).unlink()
        for a in kept:
            if id(a) in contents:
                data = contents[id(a)]
                if a.compressed:
                    data = gzip.compress(data, mtime=0)
                (d / a.final).write_bytes(data)
        if what:
            log.write_bytes(b"")
    entries.update(new_entries)
    state.save(ctx.state_path, doc)
    return out
